INSERT INTO "aid_entries" ("id","department_id","title","summary","body","contact_name","contact_phone","contact_email","location","category","source","status","submitted_by_name","submitted_by_contact","created_at","updated_at","published_at","information") VALUES(124,11,'Banco Distrital de Sangre IDCBIS','El Banco Distrital de Sangre IDCBIS ha enviado 89 unidades de componentes sanguíneos a Quibdó e invita a donar.',replace('Las autoridades invitan a la ciudadanía a donar para mantener las reservas y continuar atendiendo a los pacientes en las zonas afectadas. De domingo a domingo de 8:00 a.m. a 5:00 p.m. Revisar idcbis.org.co/banco-distrital-de-sangre para confirmar los puntos, ya que constantemente los están actualizando y ubican jornadas de donación adicionales.\nViernes 14 de agosto: Secretaría Distrital de Salud, 8:00 a.m. a 5:00 p.m.\nSábado 15 de agosto: Centro Comercial Plaza Imperial, 11:00 a.m. a 6:00 p.m.\nDomingo 16 de agosto: Iglesia María Madre Admirable, 8:00 a.m. a 3:30 p.m.; Parque Timiza, 9:00 a.m. a 4:30 p.m.; Parque San Andrés, 9:00 a.m. a 4:30 p.m.\nLunes 17 de agosto: Parque El Tunal, 9:30 a.m. a 5:30 p.m.; Parque Gilma Jiménez, 9:00 a.m. a 4:30 p.m.; Centro Comercial Plaza Imperial, 10:30 a.m. a 6:00 p.m.','\n',char(10)),NULL,NULL,NULL,'Bogotá. Confirmar puntos en idcbis.org.co/banco-distrital-de-sangre','Banco de sangre','Guía de puntos de acopio y ayudas humanitarias — AfroUp, actualización 14 de agosto de 2026','published',NULL,NULL,'2026-08-15 20:35:58','2026-08-15 20:35:59','2026-08-14T00:00:00Z','<p>Bogotá. Confirmar puntos en idcbis.org.co/banco-distrital-de-sangre<br>El Banco Distrital de Sangre IDCBIS ha enviado 89 unidades de componentes sanguíneos a Quibdó e invita a donar.<br>Las autoridades invitan a la ciudadanía a donar para mantener las reservas y continuar atendiendo a los pacientes en las zonas afectadas. De domingo a domingo de 8:00 a.m. a 5:00 p.m. Revisar idcbis.org.co/banco-distrital-de-sangre para confirmar los puntos, ya que constantemente los están actualizando y ubican jornadas de donación adicionales.<br>Viernes 14 de agosto: Secretaría Distrital de Salud, 8:00 a.m. a 5:00 p.m.<br>Sábado 15 de agosto: Centro Comercial Plaza Imperial, 11:00 a.m. a 6:00 p.m.<br>Domingo 16 de agosto: Iglesia María Madre Admirable, 8:00 a.m. a 3:30 p.m.; Parque Timiza, 9:00 a.m. a 4:30 p.m.; Parque San Andrés, 9:00 a.m. a 4:30 p.m.<br>Lunes 17 de agosto: Parque El Tunal, 9:30 a.m. a 5:30 p.m.; Parque Gilma Jiménez, 9:00 a.m. a 4:30 p.m.; Centro Comercial Plaza Imperial, 10:30 a.m. a 6:00 p.m.</p>');
