PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE IF NOT EXISTS "d1_migrations"(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE departments (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  slug TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL
);
CREATE TABLE aid_entries (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  department_id INTEGER NOT NULL REFERENCES departments(id),
  title TEXT NOT NULL,
  summary TEXT,
  body TEXT,
  contact_name TEXT,
  contact_phone TEXT,
  contact_email TEXT,
  location TEXT,
  category TEXT,
  source TEXT,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('published', 'pending', 'rejected')),
  submitted_by_name TEXT,
  submitted_by_contact TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now')),
  published_at TEXT
, information TEXT);
CREATE TABLE admin_sessions (
  id TEXT PRIMARY KEY,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  expires_at TEXT NOT NULL
);
CREATE TABLE admin_credentials (
  username TEXT PRIMARY KEY,
  password_salt TEXT NOT NULL,
  password_hash TEXT NOT NULL,
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE auth_attempts (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  ip TEXT NOT NULL,
  action TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE afroup_users (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  email TEXT NOT NULL UNIQUE,
  password_hash TEXT NOT NULL,
  verified_at TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
, bio TEXT, avatar_url TEXT);
CREATE TABLE afroup_email_verifications (
  token TEXT PRIMARY KEY,
  user_id INTEGER NOT NULL REFERENCES afroup_users(id) ON DELETE CASCADE,
  expires_at TEXT NOT NULL,
  consumed_at TEXT
);
CREATE TABLE admin_modules (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  slug TEXT NOT NULL UNIQUE,
  description TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE admin_permissions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  module_id INTEGER NOT NULL REFERENCES admin_modules(id) ON DELETE CASCADE,
  action TEXT NOT NULL CHECK (action IN ('create', 'read', 'update', 'delete')),
  name TEXT NOT NULL UNIQUE,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE admin_roles (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL UNIQUE,
  description TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE admin_role_permissions (
  role_id INTEGER NOT NULL REFERENCES admin_roles(id) ON DELETE CASCADE,
  permission_id INTEGER NOT NULL REFERENCES admin_permissions(id) ON DELETE CASCADE, parent INTEGER NOT NULL DEFAULT 0 CHECK (parent IN (0, 1)), quota INTEGER, translate TEXT NOT NULL DEFAULT 'none'
  CHECK (translate IN ('none', 'manual', 'ai')), translate_manual INTEGER NOT NULL DEFAULT 0
  CHECK (translate_manual IN (0, 1)), translate_ai INTEGER NOT NULL DEFAULT 0
  CHECK (translate_ai IN (0, 1)),
  PRIMARY KEY (role_id, permission_id)
);
CREATE TABLE admin_user_permissions (
  user_id INTEGER NOT NULL REFERENCES admin_users(id) ON DELETE CASCADE,
  permission_id INTEGER NOT NULL REFERENCES admin_permissions(id) ON DELETE CASCADE, parent INTEGER NOT NULL DEFAULT 0 CHECK (parent IN (0, 1)), quota INTEGER, translate TEXT NOT NULL DEFAULT 'none'
  CHECK (translate IN ('none', 'manual', 'ai')), translate_manual INTEGER NOT NULL DEFAULT 0
  CHECK (translate_manual IN (0, 1)), translate_ai INTEGER NOT NULL DEFAULT 0
  CHECK (translate_ai IN (0, 1)),
  PRIMARY KEY (user_id, permission_id)
);
CREATE TABLE IF NOT EXISTS "admin_users" (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  email TEXT NOT NULL UNIQUE,
  password_hash TEXT,
  role_id INTEGER REFERENCES admin_roles(id) ON DELETE SET NULL,
  is_active INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0, 1)),
  invite_pending INTEGER NOT NULL DEFAULT 1 CHECK (invite_pending IN (0, 1)),
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
, created_by INTEGER);
CREATE TABLE admin_user_invitations (
  token TEXT PRIMARY KEY,
  user_id INTEGER NOT NULL REFERENCES admin_users(id) ON DELETE CASCADE,
  expires_at TEXT NOT NULL,
  consumed_at TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE afroup_sessions (
  token TEXT PRIMARY KEY,
  user_id INTEGER NOT NULL REFERENCES afroup_users(id) ON DELETE CASCADE,
  expires_at TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE afroup_password_resets (
  token TEXT PRIMARY KEY,
  user_id INTEGER NOT NULL REFERENCES afroup_users(id) ON DELETE CASCADE,
  expires_at TEXT NOT NULL,
  consumed_at TEXT,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE admin_parent_grants (
  child_id INTEGER NOT NULL REFERENCES admin_users(id) ON DELETE CASCADE,
  parent_id INTEGER NOT NULL REFERENCES admin_users(id) ON DELETE CASCADE,
  action TEXT NOT NULL CHECK (action IN ('create', 'read', 'update', 'delete')),
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  PRIMARY KEY (child_id, parent_id, action),
  CHECK (child_id != parent_id)
);
CREATE TABLE site_languages (
  code TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  native_name TEXT NOT NULL,
  is_visible INTEGER NOT NULL DEFAULT 0 CHECK (is_visible IN (0, 1)),
  is_pillar INTEGER NOT NULL DEFAULT 0 CHECK (is_pillar IN (0, 1)),
  sort_order INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE site_language_dictionaries (
  code TEXT PRIMARY KEY REFERENCES site_languages(code) ON DELETE CASCADE,
  dictionary TEXT NOT NULL,
  updated_at TEXT NOT NULL DEFAULT (datetime('now'))
);
CREATE TABLE afroup_user_bios (
  user_id INTEGER NOT NULL REFERENCES afroup_users(id) ON DELETE CASCADE,
  locale TEXT NOT NULL,
  body TEXT NOT NULL,
  updated_at TEXT NOT NULL DEFAULT (datetime('now')),
  PRIMARY KEY (user_id, locale)
);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_aid_entries_department_status ON aid_entries (department_id, status);
CREATE INDEX idx_aid_entries_status ON aid_entries (status);
CREATE INDEX idx_admin_sessions_expires ON admin_sessions (expires_at);
CREATE INDEX idx_auth_attempts_lookup
  ON auth_attempts (ip, action, created_at);
CREATE INDEX idx_afroup_users_email ON afroup_users (email);
CREATE INDEX idx_afroup_email_verifications_user ON afroup_email_verifications (user_id);
CREATE UNIQUE INDEX idx_admin_permissions_module_action ON admin_permissions (module_id, action);
CREATE INDEX idx_admin_users_email ON admin_users (email);
CREATE INDEX idx_admin_users_invite_pending ON admin_users (invite_pending);
CREATE INDEX idx_admin_user_invitations_user ON admin_user_invitations (user_id);
CREATE INDEX idx_afroup_sessions_user ON afroup_sessions (user_id);
CREATE INDEX idx_afroup_sessions_expires ON afroup_sessions (expires_at);
CREATE INDEX idx_afroup_password_resets_user ON afroup_password_resets (user_id);
CREATE INDEX idx_afroup_password_resets_expires ON afroup_password_resets (expires_at);
CREATE INDEX idx_admin_users_created_by ON admin_users (created_by);
CREATE INDEX idx_admin_parent_grants_parent ON admin_parent_grants (parent_id);
CREATE INDEX idx_admin_parent_grants_child ON admin_parent_grants (child_id);
CREATE INDEX idx_afroup_user_bios_locale ON afroup_user_bios (locale);
